// Universal Prospect & LinkedIn URL Normalizer (Supports Google Sheets, SQL/NoSQL DBs, or Webhook payloads)
const rawItems = $input.all();
const results = [];

const getField = (row, ...keys) => {
  for (const k of keys) {
    if (row[k] !== undefined && row[k] !== null && String(row[k]).trim() !== '') {
      return String(row[k]).trim();
    }
  }
  const lowerMap = {};
  for (const [rk, rv] of Object.entries(row)) {
    lowerMap[rk.toLowerCase().replace(/[^a-z0-9]/g, '')] = rv;
  }
  for (const k of keys) {
    const cleanK = k.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (lowerMap[cleanK] !== undefined && lowerMap[cleanK] !== null && String(lowerMap[cleanK]).trim() !== '') {
      return String(lowerMap[cleanK]).trim();
    }
  }
  return '';
};

const normalizeLinkedInUrl = (rawUrl) => {
  let u = String(rawUrl || '').trim();
  if (!u) return '';
  if (!/^https?:\/\//i.test(u) && u.toLowerCase().includes('linkedin.com/')) {
    u = 'https://' + u.replace(/^\/+/, '');
  }
  return u.split('?')[0].replace(/\/+$/, '');
};

for (let i = 0; i < rawItems.length; i++) {
  const row = rawItems[i].json?.body || rawItems[i].json || {};
  const status = getField(row, 'Lead Status', 'lead_status', 'Status', 'status').toLowerCase();
  if (['completed', 'omnichannel sent', 'rejected', 'in progress'].includes(status)) {
    continue;
  }

  const linkedinUrl = normalizeLinkedInUrl(
    getField(row, 'LinkedIn Profile', 'Linkedin Profile', 'LinkedIn URL', 'linkedin_url', 'linkedin_profile', 'person_linkedin_url', 'linkedinUrl', 'profile_url', 'linkedin')
  );

  const firstName = getField(row, 'First Name', 'first_name', 'firstName');
  const lastName = getField(row, 'Last Name', 'last_name', 'lastName');
  const jobTitle = getField(row, 'Job Title', 'job_title', 'jobTitle', 'Title', 'Role', 'Designation');
  const companyName = getField(row, 'Company Name for Emails', 'Company Name', 'company_name', 'companyName', 'Company', 'Brand');
  const companyDomain = getField(row, 'Company Domain', 'company_domain', 'companyDomain', 'Domain', 'Website', 'website');
  const workEmail = getField(row, 'Work Email', 'work_email', 'workEmail', 'Email', 'email');

  results.push({
    json: {
      ...row,
      row_number: row.row_number || row.id || (i + 2),
      'First Name': firstName,
      'Last Name': lastName,
      'Job Title': jobTitle,
      'Company Name': companyName,
      'Company Name for Emails': getField(row, 'Company Name for Emails') || companyName,
      'Company Domain': companyDomain,
      'Work Email': workEmail,
      'LinkedIn Profile': linkedinUrl,
      linkedin_url: linkedinUrl
    }
  });
}

return results;

// Build LinkedIn context from Input Sheet fields + live Mutual Connections check
const lead = $('Loop Over Prospects').first()?.json || {};
let mutualRaw = {};
try {
  mutualRaw = $('LinkedIn: Check Mutual Connections').first()?.json || {};
} catch (e) {
  mutualRaw = {};
}

const getVal = (...keys) => {
  for (const k of keys) {
    if (lead[k] !== undefined && lead[k] !== null && String(lead[k]).trim() !== '') {
      return String(lead[k]).trim();
    }
  }
  return '';
};

const firstName = getVal('First Name', 'first_name', 'firstName');
const lastName = getVal('Last Name', 'last_name', 'lastName');
const jobTitle = getVal('Job Title', 'job_title', 'jobTitle', 'Title', 'Role');
const companyName = getVal('Company Name for Emails', 'Company Name', 'company_name', 'Company');
const companyDomain = getVal('Company Domain', 'company_domain', 'Domain', 'Website');
const linkedinUrl = getVal('LinkedIn Profile', 'linkedin_url', 'LinkedIn URL', 'linkedin_profile');

const headline = getVal('LinkedIn Headline', 'Headline', 'headline', 'Opener Hook', 'opener_hook') || mutualRaw.headline || (jobTitle && companyName ? `${jobTitle} at ${companyName}` : jobTitle);
const about = getVal('LinkedIn Summary', 'About', 'about', 'Bio', 'bio', 'Summary', 'summary', 'LinkedIn Bio') || mutualRaw.about || `${firstName} ${lastName} serves as ${jobTitle} at ${companyName}.`.trim();
const recentPosts = getVal('Recent Posts', 'Recent Activity', 'recent_posts', 'recent_activity', 'Posts', 'LinkedIn Posts') || 'No recent posts provided in input.';
const expSummary = getVal('Experience Summary', 'experience_summary', 'Experience') || `${jobTitle} at ${companyName}`.trim();

const liveNames = Array.isArray(mutualRaw.lead_colleague_names) ? mutualRaw.lead_colleague_names : [];
const boldestMutualNames = [...new Set(liveNames.map(n => String(n).trim()).filter(Boolean))];
const hasBoldestMutual = boldestMutualNames.length > 0;
const mutualOpenerPhrase = hasBoldestMutual
  ? (boldestMutualNames.length === 1
      ? `I work with ${boldestMutualNames[0]}`
      : `I work with ${boldestMutualNames[0]} and ${boldestMutualNames[1]}`)
  : '';

const connectionDegree = mutualRaw.connection_degree || getVal('Connection Degree', 'connection_degree') || '2nd';
const isAlreadyConnected = Boolean(mutualRaw.is_connected || connectionDegree === '1st');

return [{
  json: {
    linkedin_url: linkedinUrl,
    first_name: firstName,
    last_name: lastName,
    job_title: jobTitle,
    company_name: companyName,
    company_domain: companyDomain,
    headline: String(headline).substring(0, 300),
    about: String(about).substring(0, 800),
    recent_posts: String(recentPosts).substring(0, 1200),
    experience_summary: expSummary,
    connection_degree: connectionDegree,
    is_already_connected: isAlreadyConnected,
    has_boldest_mutual: hasBoldestMutual,
    boldest_mutual_names: boldestMutualNames,
    boldest_mutual_contacts: Array.isArray(mutualRaw.matched_boldest_contacts) ? mutualRaw.matched_boldest_contacts : [],
    mutual_opener_phrase: mutualOpenerPhrase,
    boldest_mutual_summary: hasBoldestMutual ? `${boldestMutualNames.join(', ')} (mutual LinkedIn connection at Boldest)` : 'None detected',
    mutual_text_raw: mutualRaw.mutual_text || '',
    open_profile: Boolean(lead['Open Profile'] || lead['open_profile'] || false)
  }
}];

const results = [];

for (const item of $input.all()) {
  let raw = item.json.text || item.json.response || item.json.output || item.json.content?.[0]?.text || item.json.content || "";
  if (typeof raw !== "string") {
    raw = JSON.stringify(raw);
  }

  let clean = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const jsonMatch = clean.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    clean = jsonMatch[0];
  }

  let parsed = {};
  try {
    parsed = JSON.parse(clean);
  } catch (e) {
    const extractField = (fieldName) => {
      const regex = new RegExp('"' + fieldName + '"\\s*:\\s*"([\\s\\S]*?)(?="\\s*,\\s*"[a-zA-Z0-9_]+"|"\\s*})');
      const match = clean.match(regex);
      return match ? match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') : '';
    };
    const scoreMatch = clean.match(/"linkedin_score"\s*:\s*([1-5])/);
    parsed = {
      linkedin_score: scoreMatch ? parseInt(scoreMatch[1], 10) : 4,
      subject_line: extractField('subject_line'),
      email_1: extractField('email_1'),
      email_2: extractField('email_2'),
      email_3: extractField('email_3'),
      linkedin_connection_note: extractField('linkedin_connection_note'),
      linkedin_dm_1_diagnostic: extractField('linkedin_dm_1_diagnostic'),
      linkedin_dm_2_followup: extractField('linkedin_dm_2_followup')
    };
  }

  const stripDashes = (str) => String(str || '').replace(/[\u2014\u2013]/g, ', ');
  const hasBracketPlaceholder = (str) => /\[[A-Za-z0-9 _'\-\/]{2,60}\]/.test(String(str || ''));

  const lead = $('Loop Over Prospects').first()?.json || {};
  const liNorm = $('Normalize LinkedIn Dossier').first()?.json || {};
  let configRow = {};
  try {
    configRow = $('Get LinkedIn Session Config').first()?.json || {};
  } catch (e) {
    configRow = {};
  }

  const firstName = lead['First Name'] || liNorm.first_name || 'there';
  const lastName = lead['Last Name'] || liNorm.last_name || '';
  const companyName = lead['Company Name for Emails'] || lead['Company Name'] || liNorm.company_name || 'your brand';
  const companyDomain = lead['Company Domain'] || liNorm.company_domain || '';
  const jobTitle = lead['Job Title'] || liNorm.job_title || 'eCommerce';
  const linkedinUrl = (lead['LinkedIn Profile'] || lead['linkedin_url'] || liNorm.linkedin_url || '').trim();

  const cleanPlaceholders = (str) => stripDashes(str)
    .replace(/\[\s*First\s*Name\s*\]/gi, firstName)
    .replace(/\[\s*(?:Clean\s*)?Brand(?:\s*Name)?\s*\]/gi, companyName)
    .replace(/\[\s*apparel_category\s*\]/gi, 'apparel')
    .trim();

  const hasBoldestMutual = Boolean(liNorm.has_boldest_mutual);
  const boldestMutualNames = Array.isArray(liNorm.boldest_mutual_names) ? liNorm.boldest_mutual_names : [];
  const mutualOpenerPhrase = String(liNorm.mutual_opener_phrase || '').trim();
  const primaryColleague = boldestMutualNames[0] || '';
  const isAlreadyConnected = Boolean(liNorm.is_already_connected);

  const defaultConnNote = hasBoldestMutual && mutualOpenerPhrase
    ? `Hey ${firstName}, ${mutualOpenerPhrase} and noticed we share a mutual connection. Saw you're leading ${jobTitle} at ${companyName}, thought it'd be great to connect here.`
    : `Hey ${firstName}, saw you're leading ${jobTitle} at ${companyName}. Really liked how you're structuring your online product pages. Thought it'd be great to connect here.`;
  let connNote = cleanPlaceholders(parsed.linkedin_connection_note || defaultConnNote);
  if (hasBracketPlaceholder(connNote)) {
    connNote = defaultConnNote;
  }
  if (hasBoldestMutual && mutualOpenerPhrase && primaryColleague) {
    const lowNote = connNote.toLowerCase();
    if (!lowNote.includes(primaryColleague.toLowerCase()) || !lowNote.includes('work with')) {
      connNote = `Hey ${firstName}, ${mutualOpenerPhrase} and noticed we share a mutual connection. Saw your work at ${companyName}, thought it'd be great to connect.`;
    }
  } else if (!hasBoldestMutual && (/\bi work with\b/i.test(connNote) || /mutual connection/i.test(connNote))) {
    connNote = defaultConnNote;
  }
  if (connNote.length > 285) {
    connNote = connNote.substring(0, 282).replace(/\s+\S*$/, '') + '...';
  }

  const defaultDmBody = `Quick question: when shoppers are choosing between sizes on ${companyName}'s PDPs, are you mostly relying on static size guides right now, or testing interactive fit guidance?`;
  const defaultDm1 = hasBoldestMutual && mutualOpenerPhrase
    ? (isAlreadyConnected
        ? `Hey ${firstName}, ${mutualOpenerPhrase} and wanted to reach out directly. ${defaultDmBody}`
        : `Thanks for connecting, ${firstName}. ${mutualOpenerPhrase}. ${defaultDmBody}`)
    : (isAlreadyConnected
        ? `Hey ${firstName}, ${defaultDmBody}`
        : `Thanks for connecting, ${firstName}. ${defaultDmBody}`);

  let dm1 = cleanPlaceholders(parsed.linkedin_dm_1_diagnostic || defaultDm1);
  // Strip any leftover hallucinated bracket placeholders like [Mutual Connection] before validating
  dm1 = dm1
    .replace(/\[[A-Za-z0-9 _'\-\/]{2,60}\]\s*(?:and\s+wanted\s+to\s+ask\s+a\s+quick\s+question:|and\s+wanted\s+to\s+reach\s+out[^.:]*[.:]?|[,.:;-]*\s*)?/gi, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
  if (!dm1 || hasBracketPlaceholder(dm1)) {
    dm1 = defaultDm1;
  }
  if (hasBoldestMutual && mutualOpenerPhrase && primaryColleague) {
    const headSlice = dm1.slice(0, 140).toLowerCase();
    if (!headSlice.includes(primaryColleague.toLowerCase()) || !headSlice.includes('work with')) {
      const cleanedTail = dm1
        .replace(/^(hi|hey|hello)\s+[^,.!\n]+[,!.]\s*/i, '')
        .replace(/^thanks for connecting[^.!?\n]*[.!?]\s*/i, '')
        .trim();
      const prefix = isAlreadyConnected
        ? `Hey ${firstName}, ${mutualOpenerPhrase}. `
        : `Thanks for connecting, ${firstName}. ${mutualOpenerPhrase}. `;
      dm1 = `${prefix}${cleanedTail || defaultDmBody}`;
    }
  } else if (!hasBoldestMutual && (/\bi work with\b/i.test(dm1) || /mutual connection/i.test(dm1))) {
    dm1 = defaultDm1;
  }

  const defaultDm2 = `No worries if the timing's off, ${firstName}. Just wanted to make sure my note didn't get buried. Happy to share how similar apparel teams are handling PDP sizing if ever useful.`;
  let dm2 = cleanPlaceholders(parsed.linkedin_dm_2_followup || defaultDm2);
  if (hasBracketPlaceholder(dm2)) dm2 = defaultDm2;

  const defaultEmail1 = `Hi ${firstName},\n\nWhile looking at ${companyName}'s product pages, I noticed how shoppers choosing across cuts and size ranges often hesitate between two sizes or order both to return one.\n\nBold Metrics builds a shopper digital twin from a few quick questions, with no photos or tape measures, to recommend their exact size style by style.\n\nOpen to seeing a quick visual mock of how this would look on one of ${companyName}'s PDPs?\n\nRegards,\n%signature%\n\nP.S. Sent you a quick connection request on LinkedIn too so you can put a face to the name.`;
  const defaultEmail2 = `Hi ${firstName},\n\nDropped a quick note on LinkedIn earlier this week, figured I'd share this here in case email is easier.\n\nBrands like Canada Goose and Helly Hansen used Bold Metrics' digital twin sizing on their PDPs to cut fit-related returns by over 20% while lifting conversion.\n\nHappy to send over a 1-page teardown for ${companyName} if useful.\n\nRegards,\n%signature%`;
  const defaultEmail3 = `Hi ${firstName},\n\nLeaving this here in case helping shoppers nail their size the first time at ${companyName} becomes a priority next quarter.\n\nRegards,\n%signature%`;

  let subj = cleanPlaceholders(parsed.subject_line || `Sizing on ${companyName} PDPs`);
  if (hasBracketPlaceholder(subj)) subj = `Sizing on ${companyName} PDPs`;
  let e1 = cleanPlaceholders(parsed.email_1 || defaultEmail1);
  if (hasBracketPlaceholder(e1)) e1 = defaultEmail1;
  let e2 = cleanPlaceholders(parsed.email_2 || defaultEmail2);
  if (hasBracketPlaceholder(e2)) e2 = defaultEmail2;
  let e3 = cleanPlaceholders(parsed.email_3 || defaultEmail3);
  if (hasBracketPlaceholder(e3)) e3 = defaultEmail3;

  results.push({
    json: {
      row_number: lead.row_number,
      first_name: lead['First Name'] || liNorm.first_name || '',
      last_name: lastName,
      job_title: lead['Job Title'] || liNorm.job_title || '',
      company_name: companyName,
      company_domain: companyDomain,
      work_email: lead['Work Email'] || '',
      linkedin_profile: linkedinUrl,
      linkedin_score: Number(parsed.linkedin_score) || 4,
      subject_line: subj,
      email_1: e1,
      email_2: e2,
      email_3: e3,
      linkedin_connection_note: connNote,
      linkedin_connection_note_length: connNote.length,
      linkedin_dm_1_diagnostic: dm1,
      linkedin_dm_2_followup: dm2,
      is_already_connected: isAlreadyConnected,
      has_boldest_mutual: hasBoldestMutual,
      boldest_mutual_names: boldestMutualNames,
      mutual_opener_phrase: mutualOpenerPhrase,
      li_at: lead.li_at || configRow.li_at || '',
      browserState: lead.browserState || configRow.BrowserState || configRow.browserState || '',
      linkedin_server_url: (lead.linkedin_server_url || configRow.LinkedInServerUrl || configRow.NgrokUrl || 'https://genethliacally-yetta-unrhythmically.ngrok-free.dev').replace(/\/+$/, ''),
      has_linkedin_url: linkedinUrl.startsWith('http')
    }
  });
}

return results;

const raw = $input.first()?.json || {};
const payload = $('Parse & Validate Omnichannel Payload').first()?.json || {};

let actionStatus = 'Connection Sent';
let details = '';

if (raw.error || raw.success === false) {
  actionStatus = 'LinkedIn Queued (Check Session)';
  details = raw.error || raw.message || 'Session or actor check needed';
} else if (Array.isArray(raw) && raw[0]) {
  actionStatus = raw[0].status || 'Connection Sent';
  details = raw[0].message || 'Success';
} else if (raw.status) {
  actionStatus = raw.status;
  details = raw.message || 'Success';
}

return [{
  json: {
    ...payload,
    linkedin_execution_status: actionStatus,
    linkedin_execution_details: details,
    executed_at: $now.toISO()
  }
}];
